from __future__ import annotations

def sum_of_squares(a, b):
    return a ** 2 + b ** 2

def is_sum_of_squares(n, e, f):
    return e ** 2 + f ** 2 == n

def product_of_sums(a, b, c, d):
    sum1 = sum_of_squares(a, b)
    sum2 = sum_of_squares(c, d)
    product = sum1 * sum2
    solutions = []
    for e in range(int(product ** 0.5) + 1):
        f_squared = product - e ** 2
        f = int(f_squared ** 0.5)
        if f * f == f_squared:
            solutions.append([min(e, f), max(e, f)])
    solutions.sort(key=lambda x: x[0])
    return solutions

def find_solutions(n):
    solutions = []
    for e in range(n + 1):
        for f in range(e, n + 1):
            if e ** 2 + f ** 2 == n:
                solutions.append([e, f])
    return solutions

def prod2sum(a, b, c, d):
    n = (a ** 2 + b ** 2) * (c ** 2 + d ** 2)
    solutions = find_solutions(n)
    valid_solutions = []
    for e, f in solutions:
        if e - f in [a * b, a * d, b * c, b * d, c * a, c * d] and e + f in [a * b, a * d, b * c, b * d, c * a, c * d]:
            valid_solutions.append([min(e, f), max(e, f)])
    return sorted(valid_solutions)

